DROP TABLE IF EXISTS `biz_event_timeline`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_event_timeline` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '时间线ID',
  `event_id` bigint NOT NULL COMMENT '应急事件ID',
  `operate_time` datetime NOT NULL COMMENT '发生时间',
  `operator_id` bigint NOT NULL COMMENT '执行者ID',
  `action_type` enum('CONFIRM','BIND','SIGN','REMARK','ATTACHMENT','CLOSED') NOT NULL COMMENT '操作类型(确认CONFIRM, 资源绑定BIND, 现场签到SIGN, 行动备注REMARK, 上传资料ATTCHMENT, 关闭事件CLOSED)',
  `action_text` varchar(512) NOT NULL COMMENT '文本说明',
  `departure` varchar(128) DEFAULT '' COMMENT '出发地',
  `destination` varchar(128) DEFAULT '' COMMENT '目的地',
  `remark` varchar(512) DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_operate_time` (`operate_time`),
  KEY `idx_event_id` (`event_id`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='事件时间线';
/*!40101 SET character_set_client = @saved_cs_client */;

