LOCK TABLES `sys_role` WRITE;
/*!40000 ALTER TABLE `sys_role` DISABLE KEYS */;
INSERT INTO `sys_role` VALUES (1,'超级管理员',1,'系统最高权限管理员，拥有所有按钮操作权限','{\"area\": [\"add\", \"edit\", \"view\", \"delete\"], \"dept\": [\"add\", \"edit\", \"view\", \"delete\"], \"role\": [\"add\", \"edit\", \"view\", \"delete\"], \"user\": [\"add\", \"edit\", \"view\", \"delete\"], \"alarm\": [\"edit\"], \"device\": [\"add\", \"edit\", \"view\", \"delete\"], \"emergency\": [\"edit\"]}','2023-03-01 09:00:00','2023-03-01 09:00:00'),(2,'系统管理员',1,'拥有系统所有权限','{\"area\": [\"add\", \"edit\", \"view\", \"delete\"], \"dept\": [\"add\", \"edit\", \"view\", \"delete\"], \"role\": [\"add\", \"edit\", \"view\", \"delete\"], \"user\": [\"add\", \"edit\", \"view\", \"delete\"], \"alarm\": [\"edit\"], \"device\": [\"add\", \"edit\", \"view\", \"delete\"], \"emergency\": [\"edit\"]}','2023-03-01 09:10:00','2023-03-01 09:10:00'),(3,'监控指挥员',2,'负责实时监控和事件确认','{\"area\": [\"view\", \"edit\"], \"dept\": [\"view\"], \"role\": [\"view\"], \"user\": [\"view\"], \"alarm\": [\"edit\"], \"device\": [\"view\", \"edit\"], \"emergency\": [\"view\"]}','2023-03-01 09:20:00','2023-03-01 09:20:00'),(4,'应急指挥员',5,'负责应急事件处置和资源调度','{\"area\": [\"view\"], \"dept\": [\"view\"], \"role\": [\"view\"], \"user\": [\"view\"], \"alarm\": [\"edit\"], \"device\": [\"view\"], \"emergency\": [\"edit\"]}','2023-03-01 09:30:00','2023-03-01 09:30:00'),(5,'数据分析员',4,'负责数据统计和报表生成','{\"area\": [\"view\"], \"dept\": [\"view\"], \"role\": [\"view\"], \"user\": [\"view\"], \"alarm\": [\"view\"], \"device\": [\"view\"], \"emergency\": [\"view\"]}','2023-03-01 09:40:00','2023-03-01 09:40:00');
/*!40000 ALTER TABLE `sys_role` ENABLE KEYS */;
